// ── O(1) — constant: index access, hash map get ──────────────────
function getFirst(arr) {
  return arr[0]; // one operation regardless of arr.length
}

// ── O(log n) — binary search (halves space each step) ────────────
function binarySearch(sorted, target) {
  let lo = 0, hi = sorted.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >>> 1;
    if (sorted[mid] === target) return mid;
    if (sorted[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}
console.log(binarySearch([1, 3, 5, 7, 9], 7)); // 3

// ── O(n) — linear: visit every element once ──────────────────────
function sum(arr) {
  return arr.reduce((acc, x) => acc + x, 0);
}

// ── O(n^2) — naive duplicate check: nested loops ─────────────────
function hasDuplicateNaive(arr) {
  for (let i = 0; i < arr.length; i++)
    for (let j = i + 1; j < arr.length; j++)
      if (arr[i] === arr[j]) return true;
  return false;
}

// ── O(n) — fast duplicate check using a Set (hash = O(1)) ────────
function hasDuplicateFast(arr) {
  const seen = new Set();
  for (const x of arr) {
    if (seen.has(x)) return true;
    seen.add(x);
  }
  return false;
}

const nums = [3, 1, 4, 1, 5, 9];
console.log(hasDuplicateNaive(nums)); // true
console.log(hasDuplicateFast(nums));  // true

